public static final boolean isContiguous(ReadablePartial partial) {
    if (partial == null) {
        throw new IllegalArgumentException("Partial must not be null");
    }
    Chronology chronology = partial.getChronology();
    if (chronology == null) {
        chronology = ISOChronology.getInstance();
    }
    int size = partial.size();
    if (size < 2) {
        return true;
    }
    DateTimeField lastField = partial.getField(0, chronology);
    for (int i = 1; i < size; i++) {
        DateTimeField field = partial.getField(i, chronology);
        DurationField range = lastField.getRangeDurationField();
        DurationField duration = field.getDurationField();
        if (range == null || duration == null || !range.equals(duration)) {
            return false;
        }
        lastField = field;
    }
    return true;
}
